  Lemma has_addr : forall f, has A f ->
    0 < f_n f <= 8 /\ 0x1000 <= f_a f /\ f_a f + f_n f <= alloc_ceiling /\
    ((LOCKA + 8 <= f_a f /\ f_a f + f_n f <= CTX_END /\ has_ctx A f) \/
