  (* [comment removed for export] *)
  Lemma has_ameta_upd_field : forall fl v f,
    (fl <> FMem /\ fl <> FW32) ->
    has (ameta_upd A ma (mupd mt fl v)) f ->
    f = FCT (ma + moff fl) (mlen fl) v \/
    (has A f /\ (f_a f + f_n f <= ma + moff fl \/ ma + moff fl + mlen fl <= f_a f)).
Proof.
