  Lemma rep_mupd : forall m fl v,
    Rep A m -> (fl <> FMem /\ fl <> FW32) -> 0 <= v ->
    Rep (ameta_upd A ma (mupd mt fl v)) (wbytes m (Z_to_bv 64 (ma + moff fl)) (Z_to_le_bytes (Z.to_nat (mlen fl)) v)).
